  f.snapshot.files.push({path: 'src/app.ts', status: 'modified'});
  assert.match(approvalHold(f.report, f.snapshot), /src\/app\.ts$/);
  f.report.gates.find(gate => gate.name === 'test_integrity').state = 'unresolved';
